/**
 * Importer (plan section 8) against a throw-away MongoDB 8.0 (mongodb-memory-server) - never the dev DB.
 * Fixture: tests/importer/fixtures/run_small, generated by lunarnav itself:
 *   python -m lunarnav.cli precompute --provider synthetic --sites "apollo11,ref_shackleton_rim,custom:-89.4500:222.6900"
 *     --start 2027-01-01T00:00:00 --end 2027-01-15T00:00:00 --dem none --horizon-method flat --dem-fallback flat
 *     --out backend/tests/importer/fixtures/run_small --run-timestamp 2026-11-14T00:00:00Z
 * Values are compared with an INDEPENDENT reader (gunzipSync + split) of the CSV files.
 */
import { existsSync, readFileSync } from 'node:fs';
import { cp, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { gunzipSync, gzipSync } from 'node:zlib';
import { createHash } from 'node:crypto';
import { MongoMemoryServer } from 'mongodb-memory-server';
import type { Db } from 'mongodb';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { closeDb, connectDb } from '../../src/db.ts';
import { ImportRefusedError, deleteRun, importRun, type ImportRunOptions } from '../../src/importer/importRun.ts';
import { CsvFormatError, parseBoolCell, parseNumberCell } from '../../src/importer/csv.ts';
import { southPolarXY } from '../../src/importer/catalog.ts';
import { resolveInside } from '../../src/importer/files.ts';
import { collectionSizes } from '../../src/importer/stats.ts';
import { SERIES_FIELD_INFO } from '../../src/contract/series.ts';
import {
  chooseBinS,
  dataCollections,
  getDefaultRunId,
  getHorizon,
  getRun,
  getSample,
  getSeries,
  getSite,
  getSites,
  getSummary,
  getWindows,
  listRuns,
  listSites,
  resolveRun,
  streamSeries,
  type MinMaxColumn,
  type SeriesValue,
} from '../../src/repos/index.ts';

import { SAMPLE_DIR } from '../sample.ts';

const here = path.dirname(fileURLToPath(import.meta.url));
const FIXTURE = path.join(here, 'fixtures', 'run_small');
const REPO = path.resolve(here, '..', '..', '..');
const SAMPLE = SAMPLE_DIR;
const CATALOG = path.join(REPO, 'lunarnav', 'catalog', 'sites.json');
const PYTHON = process.platform === 'win32' ? path.join(REPO, '.venv', 'Scripts', 'python.exe') : path.join(REPO, '.venv', 'bin', 'python');
const HAS_PYTHON = existsSync(PYTHON);
const CUSTOM = 'custom:-89.4500:222.6900';
/**
 * Pinned test server = package.json config.mongodbMemoryServer.version (VPS major 8.0.x). Not imported from
 * tests/helpers.ts on purpose: that module loads the whole app; the importer tests only need the data layer.
 */
const MONGOMS_VERSION = (JSON.parse(readFileSync(path.join(here, '..', '..', 'package.json'), 'utf8')) as { config: { mongodbMemoryServer: { version: string } } })
  .config.mongodbMemoryServer.version;

interface Manifest {
  params_fingerprint: string;
  parameters: { site_ids: string[]; n_samples: number; step_s: number; start_utc: string; end_utc: string };
  files: Record<string, string>;
}
interface SitesJson {
  sites: { id: string; files: { visibility: string; windows: string; horizon: string } }[];
}

const readJson = async <T>(p: string): Promise<T> => JSON.parse(await readFile(p, 'utf8')) as T;

/** Independent CSV reader: header + rows of raw cells (visibility files have no quoting). */
async function rawCsv(file: string): Promise<{ header: string[]; rows: string[][] }> {
  const buf = await readFile(file);
  const text = (file.endsWith('.gz') ? gunzipSync(buf) : buf).toString('utf8');
  const lines = text.split(/\r?\n/).filter((l) => l.length > 0);
  const header = (lines[0] ?? '').split(',');
  return { header, rows: lines.slice(1).map((l) => l.split(',')) };
}

let mongo: MongoMemoryServer;
let db: Db;
let work: string;
let dataDir: string;
let manifest: Manifest;
let sitesJson: SitesJson;
let RUN_ID: string;

const baseOpts = (over: Partial<ImportRunOptions> = {}): ImportRunOptions => ({
  dir: FIXTURE,
  check: HAS_PYTHON ? { pythonBin: PYTHON, cwd: REPO, timeoutMs: 120_000 } : false,
  dataDir,
  catalogPath: CATALOG,
  ...over,
});

/** Copy the fixture to a temp dir (to corrupt it). */
async function fixtureCopy(name: string): Promise<string> {
  const d = path.join(work, name);
  await cp(FIXTURE, d, { recursive: true });
  return d;
}

/** Rewrite manifest.files[rel] after editing a file so only the content (not the checksum) is wrong. */
async function refreshChecksum(dir: string, rel: string): Promise<void> {
  const mPath = path.join(dir, 'manifest.json');
  const m = await readJson<Manifest & Record<string, unknown>>(mPath);
  m.files[rel] = createHash('sha256').update(await readFile(path.join(dir, ...rel.split('/')))).digest('hex');
  await writeFile(mPath, JSON.stringify(m, null, 1));
}

beforeAll(async () => {
  mongo = await MongoMemoryServer.create({ binary: { version: MONGOMS_VERSION } });
  db = await connectDb(mongo.getUri(), 'lunarnav_importer_test');
  work = await mkdtemp(path.join(os.tmpdir(), 'lunarnav-import-'));
  dataDir = path.join(work, 'data');
  manifest = await readJson<Manifest>(path.join(FIXTURE, 'manifest.json'));
  sitesJson = await readJson<SitesJson>(path.join(FIXTURE, 'sites.json'));
  RUN_ID = `pf_${manifest.params_fingerprint}`;
});

afterAll(async () => {
  await closeDb();
  await mongo?.stop();
  if (work) await rm(work, { recursive: true, force: true });
});

describe('cell parsing (OUTPUT_SPEC section 1)', () => {
  it('booleans are exactly "1"/"0"', () => {
    expect(parseBoolCell('1', 'x')).toBe(true);
    expect(parseBoolCell('0', 'x')).toBe(false);
    for (const bad of ['true', 'True', '', '2', ' 1']) expect(() => parseBoolCell(bad, 'x')).toThrow(CsvFormatError);
  });
  it('numbers: empty -> null, nan/inf/hex rejected, decimal text -> nearest double', () => {
    expect(parseNumberCell('', 'x')).toBeNull();
    expect(parseNumberCell('102.591720', 'x')).toBe(102.59172);
    expect(parseNumberCell('-0.086937', 'x')).toBe(-0.086937);
    expect(parseNumberCell('1.5e-7', 'x')).toBe(1.5e-7);
    expect(parseNumberCell('147400637.151', 'x')).toBe(147400637.151);
    for (const bad of ['nan', 'NaN', 'inf', '-inf', 'Infinity', '0x10', ' ', '1,5']) expect(() => parseNumberCell(bad, 'x')).toThrow(CsvFormatError);
  });
  it('rejects unsafe relative paths', () => {
    expect(() => resolveInside(work, '../x.csv')).toThrow(/unsafe/);
    expect(() => resolveInside(work, '/etc/passwd')).toThrow(/unsafe/);
    expect(() => resolveInside(work, 'sites\\a.csv')).toThrow(/unsafe/);
    expect(resolveInside(work, 'sites/a/b.csv')).toBe(path.join(work, 'sites', 'a', 'b.csv'));
  });
  it('south polar stereographic map position', () => {
    expect(southPolarXY(-89.4505, 222.84)).toEqual({ projection: 'south_polar_stereographic_R1737.4km', x_km: -11.33, y_km: -12.218 });
    expect(southPolarXY(0.67416, 23.47314)).toBeNull();
  });
});

describe('import of the run_small fixture', () => {
  it('dry run parses everything and writes nothing', async () => {
    const res = await importRun(db, baseOpts({ dryRun: true }));
    expect(res.outcome).toBe('dry_run');
    expect(res.counts.series).toBe(manifest.parameters.n_samples * manifest.parameters.site_ids.length);
    const c = dataCollections(db);
    expect(await c.runs.countDocuments({})).toBe(0);
    expect(await c.series.countDocuments({})).toBe(0);
    expect(existsSync(path.join(dataDir, 'runs', RUN_ID))).toBe(false);
  });

  it('imports: run ready, document counts equal the files', async () => {
    const res = await importRun(db, baseOpts({ setDefault: true, label: 'run_small test' }));
    expect(res.outcome).toBe('imported');
    expect(res.run_id).toBe(RUN_ID);
    if (HAS_PYTHON) expect(res.check?.ok).toBe(true);
    expect(res.source_dir).toBe(path.join(dataDir, 'runs', RUN_ID));
    expect(existsSync(path.join(res.source_dir, 'manifest.json'))).toBe(true);

    const c = dataCollections(db);
    let csvRows = 0;
    let windowsInFiles = 0;
    for (const s of sitesJson.sites) {
      const { rows } = await rawCsv(path.join(FIXTURE, s.files.visibility));
      csvRows += rows.length;
      expect(await c.series.countDocuments({ 'meta.run_id': RUN_ID, 'meta.site_id': s.id })).toBe(rows.length);
      const w = await readJson<{ sun: unknown[]; earth: unknown[]; both: unknown[] }>(path.join(FIXTURE, s.files.windows));
      windowsInFiles += w.sun.length + w.earth.length + w.both.length;
    }
    expect(csvRows).toBe(3 * 336);
    expect(await c.series.countDocuments({ 'meta.run_id': RUN_ID })).toBe(csvRows);
    expect(res.counts.series).toBe(csvRows);
    expect(await c.windows.countDocuments({ run_id: RUN_ID })).toBe(windowsInFiles);
    expect(await c.site_runs.countDocuments({ run_id: RUN_ID })).toBe(3);
    expect(await c.horizons.countDocuments({ run_id: RUN_ID })).toBe(3);
    expect(await c.sites.countDocuments({})).toBe(3);

    const run = await getRun(RUN_ID);
    expect(run?.status).toBe('ready');
    expect(run?.is_default).toBe(true);
    expect(run?.label).toBe('run_small test');
    expect(run?.n_samples).toBe(336);
    expect(run?.start.toISOString()).toBe('2027-01-01T00:00:00.000Z');
    expect(run?.stats?.series_docs).toBe(csvRows);
    expect(run?.manifest.params_fingerprint).toBe(manifest.params_fingerprint);
  });

  it('series is a time-series collection with the query index', async () => {
    const info = await db.listCollections({ name: 'series' }).toArray();
    expect(info[0]?.type).toBe('timeseries');
    const names = (await db.collection('series').indexes()).map((i) => i.name);
    expect(names).toContain('meta.run_id_1_meta.site_id_1_t_1');
  });

  it('every value round-trips exactly (floats bit-identical, booleans from 1/0, empty -> null)', async () => {
    const c = dataCollections(db);
    let checked = 0;
    let nulls = 0;
    for (const s of sitesJson.sites) {
      const { header, rows } = await rawCsv(path.join(FIXTURE, s.files.visibility));
      const docs = await c.series.find({ 'meta.run_id': RUN_ID, 'meta.site_id': s.id }).sort({ t: 1 }).toArray();
      expect(docs.length).toBe(rows.length);
      rows.forEach((row, k) => {
        const doc = docs[k] as unknown as Record<string, unknown> & { t: Date; meta: { run_id: string; site_id: string } };
        expect(doc.t.toISOString().replace('.000Z', 'Z')).toBe(row[header.indexOf('time_utc')]);
        expect(doc.meta).toEqual({ run_id: RUN_ID, site_id: s.id });
        for (const f of SERIES_FIELD_INFO) {
          const cell = row[header.indexOf(f.name)] ?? '';
          const v = doc[f.name];
          if (f.type === 'boolean') {
            expect(typeof v).toBe('boolean');
            expect(v).toBe(cell === '1');
          } else if (cell === '') {
            expect(v).toBeNull();
            nulls += 1;
          } else {
            expect(typeof v).toBe('number');
            // Object.is: exact double equality (also distinguishes -0)
            expect(Object.is(v, Number(cell))).toBe(true);
          }
          checked += 1;
        }
      });
    }
    expect(checked).toBe(3 * 336 * SERIES_FIELD_INFO.length);
    expect(nulls).toBeGreaterThan(0); // the fixture has empty hours_until_* cells
  });

  it('re-import of the same manifest is a no-op', async () => {
    const c = dataCollections(db);
    const before = await getRun(RUN_ID);
    const n0 = await c.series.countDocuments({});
    const w0 = await c.windows.countDocuments({});
    // a dry run still parses every file (it does not short-circuit) and writes nothing
    const lines: string[] = [];
    const dry = await importRun(db, baseOpts({ dryRun: true, log: { info: (m) => lines.push(m), warn: (m) => lines.push(m) } }));
    expect(dry.outcome).toBe('dry_run');
    expect(dry.counts.series).toBe(3 * 336);
    expect(lines.some((l) => l.includes('would skip'))).toBe(true);
    const res = await importRun(db, baseOpts());
    expect(res.outcome).toBe('skipped');
    expect(res.check).toBeNull(); // the idempotency check runs before the (slow) python gate
    expect(res.counts.series).toBe(3 * 336);
    const after = await getRun(RUN_ID);
    expect(after?.imported_at?.getTime()).toBe(before?.imported_at?.getTime());
    expect(after?.started_at.getTime()).toBe(before?.started_at.getTime());
    expect(await c.series.countDocuments({})).toBe(n0);
    expect(await c.windows.countDocuments({})).toBe(w0);
  });

  it('--force re-imports without duplicating documents and keeps the default flag', async () => {
    const c = dataCollections(db);
    const n0 = await c.series.countDocuments({});
    const before = await getRun(RUN_ID);
    const res = await importRun(db, baseOpts({ force: true }));
    expect(res.outcome).toBe('imported');
    expect(await c.series.countDocuments({})).toBe(n0);
    const after = await getRun(RUN_ID);
    expect(after?.imported_at?.getTime()).toBeGreaterThan(before?.imported_at?.getTime() ?? Infinity);
    expect(after?.is_default).toBe(true);
    expect(after?.label).toBe('run_small test');
  });
});

describe('import gate', () => {
  it('refuses a modified directory (checksum / python check) unless --force', async () => {
    const dir = await fixtureCopy('tampered');
    const sitesPath = path.join(dir, 'sites.json');
    await writeFile(sitesPath, (await readFile(sitesPath, 'utf8')).replace('"note":', '"note" :'));
    const c = dataCollections(db);
    const runsBefore = await c.runs.countDocuments({});
    const err = await importRun(db, baseOpts({ dir, runId: 'tampered_run' })).catch((e: unknown) => e);
    expect(err).toBeInstanceOf(ImportRefusedError);
    const reasons = (err as ImportRefusedError).reasons.join('\n');
    expect(reasons).toMatch(HAS_PYTHON ? /VIOLATION|sites\.json/ : /sites\.json: sha256/);
    expect(await c.runs.countDocuments({})).toBe(runsBefore);

    // without the python gate the node-side checksum verification still refuses
    const err2 = await importRun(db, baseOpts({ dir, runId: 'tampered_run', check: false })).catch((e: unknown) => e);
    expect(err2).toBeInstanceOf(ImportRefusedError);
    expect((err2 as ImportRefusedError).reasons.join('\n')).toMatch(/sites\.json: sha256 [0-9a-f]{64} != manifest/);

    const res = await importRun(db, baseOpts({ dir, runId: 'tampered_run', force: true }));
    expect(res.outcome).toBe('imported');
    expect(res.warnings.some((w) => w.includes('checksum (forced)'))).toBe(true);
    expect((await getRun('tampered_run'))?.status).toBe('ready');
    expect((await getRun(RUN_ID))?.is_default).toBe(true);
    await deleteRun(db, 'tampered_run');
    expect(await c.series.countDocuments({ 'meta.run_id': 'tampered_run' })).toBe(0);
    expect(await getRun('tampered_run')).toBeNull();
  });

  it.skipIf(!HAS_PYTHON)('the python check catches a content error that has a valid checksum', async () => {
    const dir = await fixtureCopy('bad_bool');
    const rel = sitesJson.sites[0]?.files.visibility ?? '';
    const file = path.join(dir, ...rel.split('/'));
    const text = gunzipSync(await readFile(file)).toString('utf8');
    const lines = text.split('\n');
    const header = (lines[0] ?? '').split(',');
    const iVis = header.indexOf('sun_visible');
    const cells = (lines[5] ?? '').split(',');
    cells[iVis] = cells[iVis] === '1' ? '0' : '1'; // flip a flag: now inconsistent with sun_fraction / windows
    lines[5] = cells.join(',');
    await writeFile(file, gzipSync(Buffer.from(lines.join('\n'))));
    await refreshChecksum(dir, rel);
    const err = await importRun(db, baseOpts({ dir, runId: 'bad_bool_run' })).catch((e: unknown) => e);
    expect(err).toBeInstanceOf(ImportRefusedError);
    expect((err as ImportRefusedError).reasons.some((r) => r.startsWith('VIOLATION'))).toBe(true);
    expect(await getRun('bad_bool_run')).toBeNull();
  });

  it('a malformed boolean marks the run failed (no python gate, valid checksum)', async () => {
    const dir = await fixtureCopy('bad_cell');
    const rel = sitesJson.sites[1]?.files.visibility ?? '';
    const file = path.join(dir, ...rel.split('/'));
    const lines = gunzipSync(await readFile(file)).toString('utf8').split('\n');
    const header = (lines[0] ?? '').split(',');
    const cells = (lines[10] ?? '').split(',');
    cells[header.indexOf('earth_visible')] = '2';
    lines[10] = cells.join(',');
    await writeFile(file, gzipSync(Buffer.from(lines.join('\n'))));
    await refreshChecksum(dir, rel);
    const err = await importRun(db, baseOpts({ dir, runId: 'bad_cell_run', check: false })).catch((e: unknown) => e);
    expect(err).toBeInstanceOf(CsvFormatError);
    expect(String(err)).toMatch(/earth_visible: expected boolean 1\/0, got "2"/);
    const run = await getRun('bad_cell_run');
    expect(run?.status).toBe('failed');
    expect(run?.error).toMatch(/expected boolean/);
    await expect(resolveRun('bad_cell_run')).rejects.toMatchObject({ code: 'RUN_NOT_READY' });
    await deleteRun(db, 'bad_cell_run');
  });
});

describe('repos (read side)', () => {
  it('runs: list, default, resolve, errors', async () => {
    const runs = await listRuns();
    expect(runs[0]?._id).toBe(RUN_ID);
    expect(await getDefaultRunId()).toBe(RUN_ID);
    expect((await resolveRun())._id).toBe(RUN_ID);
    await expect(resolveRun('nope')).rejects.toMatchObject({ code: 'RUN_NOT_FOUND' });
  });

  it('sites: rank order, join with the catalog, custom id with ":"', async () => {
    const summary = (await readFile(path.join(FIXTURE, 'summary.csv'), 'utf8')).split(/\r?\n/).slice(1).filter(Boolean);
    const order = summary.map((l) => l.split(',')[1]);
    const views = await listSites(RUN_ID);
    expect(views.map((v) => v.site_run.site_id)).toEqual(order);
    expect(views.map((v) => v.site_run.rank)).toEqual([1, 2, 3]);

    const rim = await getSite(RUN_ID, 'ref_shackleton_rim');
    expect(rim?.site?.extra).not.toBeNull();
    expect(rim?.site?.map?.projection).toBe('south_polar_stereographic_R1737.4km');
    expect(rim?.site_run.record.horizon_method).toBe('flat');
    expect('files' in (rim?.site_run.record ?? {})).toBe(false);
    const win = await readJson<{ metrics: Record<string, unknown> }>(path.join(FIXTURE, 'sites', 'ref_shackleton_rim', 'windows.json'));
    expect(rim?.site_run.metrics).toEqual(win.metrics);

    const custom = await getSite(RUN_ID, CUSTOM);
    expect(custom?.site?.origin).toBe('custom');
    expect(custom?.site?.extra).toBeNull();
    expect(custom?.site_run.files.visibility).toBe('sites/custom_-89.4500_222.6900/visibility.csv.gz');
    const apollo = await getSite(RUN_ID, 'apollo11');
    expect(apollo?.site?.map).toBeNull();

    expect((await getSites(RUN_ID, [CUSTOM, 'missing', 'apollo11'])).map((v) => v.site_run.site_id)).toEqual([CUSTOM, 'apollo11']);
    expect(await getSite(RUN_ID, 'missing')).toBeNull();
    expect((await listSites(RUN_ID, { group: 'reference' })).map((v) => v.site_run.site_id)).toEqual(['ref_shackleton_rim']);
  });

  it('summary rows are typed summary.csv values', async () => {
    const rows = await getSummary(RUN_ID);
    expect(rows).toHaveLength(3);
    const first = rows[0];
    expect(first?.rank).toBe(1);
    expect(typeof first?.longest_dark_truncated).toBe('boolean');
    const line = (await readFile(path.join(FIXTURE, 'summary.csv'), 'utf8')).split(/\r?\n/)[1]?.split(',') ?? [];
    expect(first?.score).toBe(Number(line[7]));
    expect(first?.site_id).toBe(line[1]);
  });

  it('horizon: full-resolution arrays', async () => {
    const h = await getHorizon(RUN_ID, 'apollo11');
    const { rows } = await rawCsv(path.join(FIXTURE, 'sites', 'apollo11', 'horizon_flat.csv'));
    expect(h?.az_deg).toHaveLength(rows.length);
    expect(h?.el_deg[3]).toBe(Number(rows[3]?.[1]));
    expect(h?.az_step_deg).toBe(Number(rows[1]?.[0]) - Number(rows[0]?.[0]));
    expect(h?.method).toBe('flat');
  });

  it('windows: overlap query, sorted, not clipped', async () => {
    const from = Date.parse('2027-01-05T00:00:00Z');
    const to = Date.parse('2027-01-06T00:00:00Z');
    const w = await getWindows(RUN_ID, 'apollo11', { fromMs: from, toMs: to, kinds: ['sun', 'earth'] });
    expect(Object.keys(w).sort()).toEqual(['earth', 'sun']);
    for (const list of [w.sun ?? [], w.earth ?? []]) {
      expect(list.length).toBeGreaterThan(0);
      for (const x of list) {
        expect(x.start.getTime()).toBeLessThan(to);
        expect(x.end.getTime()).toBeGreaterThan(from);
      }
      for (let i = 1; i < list.length; i++) expect(list[i]?.start.getTime()).toBe(list[i - 1]?.end.getTime());
    }
    const all = await getWindows(RUN_ID, 'apollo11');
    const file = await readJson<{ sun: { start: string }[] }>(path.join(FIXTURE, 'sites', 'apollo11', 'windows.json'));
    expect(all.sun?.map((x) => x.start.toISOString().replace('.000Z', 'Z'))).toEqual(file.sun.map((x) => x.start));
  });

  it('series: exact samples, binned sample + minmax, sample lookup, stream', async () => {
    const run = await resolveRun(RUN_ID);
    const t0 = run.start.getTime();
    const { header, rows } = await rawCsv(path.join(FIXTURE, 'sites', 'apollo11', 'visibility.csv.gz'));
    const col = (f: string): string[] => rows.map((r) => r[header.indexOf(f)] ?? '');
    const el = col('sun_el_deg').map(Number);
    const vis = col('sun_visible').map((c) => c === '1');

    const full = await getSeries('apollo11', run, t0, run.end.getTime(), ['sun_el_deg', 'sun_visible', 'hours_until_earthset']);
    expect(full.n).toBe(336);
    expect(full.fields['sun_el_deg']).toEqual(el);
    expect(full.fields['sun_visible']).toEqual(vis);
    expect((full.fields['hours_until_earthset'] as SeriesValue[]).every((v) => v === null)).toBe(true);

    // a window of 10 h starting at sample 7
    const part = await getSeries('apollo11', run, t0 + 7 * 3600_000, t0 + 17 * 3600_000, ['sun_el_deg']);
    expect(part.fields['sun_el_deg']).toEqual(el.slice(7, 17));

    const bin = chooseBinS(336, 3600, 50);
    expect(bin).toBe(7 * 3600);
    const sampled = await getSeries('apollo11', run, t0, run.end.getTime(), ['sun_el_deg'], { bin_s: bin });
    expect(sampled.n).toBe(48);
    expect(sampled.fields['sun_el_deg']).toEqual(el.filter((_v, i) => i % 7 === 0));

    const mm = await getSeries('apollo11', run, t0, run.end.getTime(), ['sun_el_deg', 'sun_visible'], { bin_s: bin, agg: 'minmax' });
    const m = mm.fields['sun_el_deg'] as MinMaxColumn;
    const chunk = (i: number): number[] => el.slice(i * 7, i * 7 + 7);
    expect(m.min[3]).toBe(Math.min(...chunk(3)));
    expect(m.max[3]).toBe(Math.max(...chunk(3)));
    const frac = mm.fields['sun_visible'] as SeriesValue[];
    const v5 = vis.slice(35, 42);
    expect(frac[5]).toBeCloseTo(v5.filter(Boolean).length / 7, 12);

    await expect(getSeries('apollo11', run, t0, t0 + 3600_000, ['sun_el_deg'], { bin_s: 1800 })).rejects.toThrow(RangeError);

    const s = await getSample('apollo11', run, t0 + 12 * 3600_000);
    expect(s?.sun_el_deg).toBe(el[12]);
    expect(s?.t.getTime()).toBe(t0 + 12 * 3600_000);
    expect(await getSample('apollo11', run, t0 - 3600_000)).toBeNull();

    let n = 0;
    let last = -Infinity;
    for await (const r of streamSeries(CUSTOM, run, t0, t0 + 100 * 3600_000, ['earth_el_deg'])) {
      expect(r.t.getTime()).toBeGreaterThan(last);
      last = r.t.getTime();
      expect(typeof r.earth_el_deg).toBe('number');
      n += 1;
    }
    expect(n).toBe(100);
  });

  it('collection sizes are measurable', async () => {
    const sizes = await collectionSizes(db);
    const series = sizes.collections.find((c) => c.name === 'series');
    expect(series?.count).toBe(3 * 336);
    expect(series?.storageSize).toBeGreaterThan(0);
    expect(sizes.db.storageSize).toBeGreaterThan(0);
  });
});

